        (6, "दूर दृष्टि दोष (Hypermetropia) के निवारण हेतु किस लेंस का उपयोग किया जाता है?", ["अवतल लेंस", "उत्तल लेंस (Convex Lens)", "समतल दर्पण", "अवतल दर्पण"], "B", "उत्तल लेंस अभिसारी होता है जो किरणों को पहले मोड़कर रेटिना पर प्रतिबिंब बनाता है।", "NMMS Delhi 2022"),
        (7, "दांतों के डॉक्टर द्वारा मरीज के दांतों का बड़ा प्रतिबिंब देखने के लिए कौन-सा दर्पण प्रयुक्त होता है?", ["उत्तल दर्पण", "अवतल दर्पण (Concave Mirror)", "समतल दर्पण", "उत्तल लेंस"], "B", "अवतल दर्पण वस्तु को बहुत पास रखने पर सीधा व बड़ा आभासी प्रतिबिंब दिखाता है।", "NMMS Bihar 2022"),
        (8, "गाड़ियों की हेडलाइट (Headlights) में कौन-सा दर्पण उपयोग में लाया जाता है?", ["उत्तल दर्पण", "अवतल परवलयिक दर्पण (Concave)", "समतल दर्पण", "बेलनाकार दर्पण"], "B", "अवतल दर्पण बल्ब से निकलने वाले प्रकाश को समानांतर शक्तिशाली पुंज में बदल देता है।", "NMMS UP 2023"),
        (9, "किसी परिपथ में विभवांतर मापने के लिए वोल्टमीटर को किस क्रम में जोड़ा जाता है?", ["श्रेणीक्रम में", "समांतर क्रम में (Parallel)", "मिश्रित क्रम में", "किसी भी क्रम में"], "B", "वोल्टमीटर का प्रतिरोध बहुत उच्च होता है, अतः इसे सदैव समांतर क्रम में जोड़ा जाता है।", "NMMS MP 2022"),
        (10, "घरों में प्रयुक्त विद्युत उपकरण (पंखा, बल्ब, टीवी) किस क्रम में जुड़े होते हैं?", ["श्रेणीक्रम में", "समांतर क्रम (Parallel Connection)", "चक्रीय क्रम में", "अनियमित क्रम में"], "B", "समांतर क्रम में सभी उपकरणों को समान 220V वोल्टेज मिलता है और एक बंद होने पर दूसरा चालू रहता है।", "NMMS Rajasthan 2021"),
        (11, "पृथ्वी के केंद्र (Center of Earth) पर किसी वस्तु का भार कितना होगा?", ["अधिकतम", "शून्य (Zero)", "ध्रुवों के बराबर", "अनंत"], "B", "पृथ्वी के केंद्र पर गुरुत्वीय त्वरण g = 0 होता है, अतः भार W = m × 0 = 0 होगा।", "NMMS All India 2022"),
        (12, "पृथ्वी पर किसी वस्तु का भार सर्वाधिक कहाँ पर होता है?", ["भूमध्य रेखा पर", "ध्रुवों पर (Poles)", "कर्क रेखा पर", "मकर रेखा पर"], "B", "ध्रुवों पर पृथ्वी की त्रिज्या न्यूनतम होने से गुरुत्वीय त्वरण g का मान सर्वाधिक होता है।", "NMMS Gujarat 2023"),
        (13, "पेंडुलम घड़ी (सरल लोलक) का आवर्तकाल किस पर निर्भर करता है?", ["गोलक के द्रव्यमान पर", "लोलक की प्रभावी लंबाई पर", "गोलक के रंग पर", "समय पर"], "B", "T = 2π√(L/g), अतः आवर्तकाल केवल लोलक की लंबाई (L) और g पर निर्भर करता है।", "NMMS Bihar 2021"),
        (14, "ध्वनि की तीव्रता (Loudness) का मात्रक क्या है?", ["हर्ट्ज़", "डेसिबल (Decibel - dB)", "पास्कल", "मीटर"], "B", "ध्वनि की तीव्रता और शोर का स्तर डेसिबल (dB) में मापा जाता है (80 dB से ऊपर शोर हानिकारक है)।", "NMMS UP 2021"),
        (15, "पराबैंगनी किरणों (UV Rays) की खोज किस वैज्ञानिक ने की थी?", ["रॉन्टजन", "जोहान रिटर (Johann Ritter)", "हर्शेल", "न्यूटन"], "B", "1801 में जोहान रिटर ने पराबैंगनी किरणों की खोज की थी।", "NMMS MP 2023"),
        (16, "अम्लराज (Aqua Regia) सांद्र HCl और सांद्र HNO₃ का किस अनुपात में ताजा मिश्रण होता है?", ["1 : 3", "3 : 1 (3 HCl + 1 HNO₃)", "2 : 1", "1 : 1"], "B", "3 भाग सांद्र हाइड्रोक्लोरिक अम्ल और 1 भाग सांद्र नाइट्रिक अम्ल का मिश्रण सोना भी घोल देता है।", "NMMS Rajasthan 2023"),
        (17, "सोने एवं चांदी के आभूषणों को साफ करने हेतु सुनार द्वारा किस अम्ल का उपयोग किया जाता है?", ["सल्फ्यूरिक अम्ल", "नाइट्रिक अम्ल (HNO₃)", "एसिटिक अम्ल", "हाइड्रोक्लोरिक अम्ल"], "B", "नाइट्रिक अम्ल (शोरे का अम्ल) सोने और चांदी की अशुद्धियों को साफ करने हेतु उपयोग में आता है।", "NMMS Delhi 2023"),
        (18, "वाहनों की बैटरियों (Lead Storage Battery) में कौन-सा अम्ल भरा जाता है?", ["नाइट्रिक अम्ल", "सल्फ्यूरिक अम्ल (H₂SO₄)", "हाइड्रोक्लोरिक अम्ल", "फॉर्मिक अम्ल"], "B", "सल्फ्यूरिक अम्ल (गंधक का अम्ल) को 'रसायनों का राजा' कहते हैं, यह लेड बैटरियों में प्रयुक्त होता है।", "NMMS Bihar 2023"),
        (19, "पेट की अम्लीयता (एसिडिटी) दूर करने हेतु प्रयुक्त 'मिल्क ऑफ मैग्नीशिया' का रासायनिक नाम क्या है?", ["कैल्शियम कार्बोनेट", "मैग्नीशियम हाइड्रोक्साइड [Mg(OH)₂]", "सोडियम हाइड्रोक्साइड", "पोटेशियम क्लोराइड"], "B", "मैग्नीशियम हाइड्रोक्साइड एक दुर्बल प्रति-अम्ल (Antacid) है जो अतिरिक्त पेट के अम्ल को शांत करता है।", "NMMS UP 2022"),
        (20, "शुष्क बुझा हुआ चूना (Slaked Lime) का रासायनिक सूत्र क्या है?", ["CaO", "Ca(OH)₂", "CaCO₃", "CaCl₂"], "B", "बिना बुझे चूने (CaO) में पानी डालने पर बुझा हुआ चूना [Ca(OH)₂] बनता है।", "NMMS MP 2022"),
        (21, "संगमरमर (Marble), खड़िया एवं चूना-पत्थर का मुख्य रासायनिक घटक क्या है?", ["कैल्शियम सल्फेट", "कैल्शियम कार्बोनेट (CaCO₃)", "कैल्शियम ऑक्साइड", "कैल्शियम नाइट्रेट"], "B", "संगमरमर, चूना-पत्थर, चाक और अंडे का छिलका सभी कैल्शियम कार्बोनेट (CaCO₃) के रूप हैं।", "NMMS Haryana 2022"),
        (22, "हंसाने वाली गैस (Laughing Gas) का रासायनिक नाम क्या है?", ["नाइट्रिक ऑक्साइड", "नाइट्रस ऑक्साइड (N₂O)", "नाइट्रोजन डाइऑक्साइड", "अमोनिया"], "B", "नाइट्रस ऑक्साइड (N₂O) को सूंघने पर उत्तेजना व हंसी आती है, इसे लाफिंग गैस कहते हैं।", "NMMS Rajasthan 2022"),
        (23, "अश्रु गैस (Tear Gas) के रूप में मुख्य रूप से कौन-सा रासायनिक यौगिक प्रयुक्त होता है?", ["क्लोरोपिक्रिन (Chloropicrin)", "मीथेन", "ईथेन", "कार्बन मोनोऑक्साइड"], "A", "भीड़ को तितर-बितर करने हेतु पुलिस अश्रु गैस (क्लोरोपिक्रिन) का उपयोग करती है।", "NMMS All India 2023"),
        (24, "शुष्क बर्फ (Dry Ice) किसे कहा जाता है?", ["ठोस नाइट्रोजन", "ठोस कार्बन डाइऑक्साइड (Solid CO₂)", "बर्फ और नमक का मिश्रण", "ठोस हाइड्रोजन"], "B", "ठोस CO₂ को अत्यधिक दाब पर जमाया जाता है; गर्म करने पर यह बिना द्रव बने सीधे गैस बनती है।", "NMMS Gujarat 2022"),
        (25, "कच्चे फलों को कृत्रिम रूप से पकाने के लिए किस गैस का उपयोग किया जाता है?", ["मीथेन", "एसिटिलीन / एथिलीन (Ethylene)", "ईथेन", "हाइड्रोजन"], "B", "एथिलीन एक पादप हार्मोन है तथा कार्बाइड से निकलने वाली एसिटिलीन फलों को जल्दी पकाती है।", "NMMS Bihar 2022"),
        (26, "गोबर गैस (बायोगैस) का मुख्य ज्वलनशील घटक कौन-सी गैस होती है?", ["कार्बन डाइऑक्साइड", "मीथेन (CH₄ - लगभग 65%)", "ब्यूटेन", "प्रोपेन"], "B", "बायोगैस संयंत्र में अवायवीय जीवाणुओं द्वारा गोबर के सड़ने से प्रचुर मात्रा में मीथेन बनती है।", "NMMS UP 2023"),
        (27, "जल की स्थायी कठोरता दूर करने के लिए किसका उपयोग किया जाता है?", ["ब्लीचिंग पाउडर", "धावन सोडा (Washing Soda)", "साधारण नमक", "नीला थोथा"], "B", "धावन सोडा (Na₂CO₃) जल में घुले कैल्शियम व मैग्नीशियम के सल्फेट/क्लोराइड को अवक्षेपित कर देता है।", "NMMS MP 2023"),
        (28, "नीला थोथा (Blue Vitriol) का रासायनिक नाम क्या है?", ["फेरस सल्फेट", "कॉपर सल्फेट (CuSO₄.5H₂O)", "जिंक सल्फेट", "मैग्नीशियम सल्फेट"], "B", "कॉपर सल्फेट पेंटाहाइड्रेट को नीला थोथा या तूतिया कहा जाता है।", "NMMS Rajasthan 2021"),
        (29, "हरा कसीस (Green Vitriol) का रासायनिक नाम क्या है?", ["कॉपर सल्फेट", "फेरस सल्फेट (FeSO₄.7H₂O)", "जिंक सल्फेट", "एल्युमिनियम सल्फेट"], "B", "फेरस सल्फेट हेप्टाहाइड्रेट को हरा कसीस कहते हैं।", "NMMS Delhi 2023"),
        (30, "सफेद थोथा (White Vitriol) किसे कहा जाता है?", ["जिंक सल्फेट (ZnSO₄.7H₂O)", "कैल्शियम सल्फेट", "सोडियम सल्फेट", "बेरियम सल्फेट"], "A", "जिंक सल्फेट के क्रिस्टल को सफेद थोथा कहा जाता है।", "NMMS Bihar 2021"),
        (31, "मानव शरीर में रक्त का शुद्धिकरण (रक्त छनन) किस अंग में होता है?", ["फेफड़े में", "हृदय में", "वृक्क / गुर्दे (Kidneys) में", "यकृत में"], "C", "वृक्क (Kidney) रक्त से यूरिया, यूरिक अम्ल और अतिरिक्त लवणों को छानकर मूत्र बनाता है।", "NMMS UP 2021"),
        (32, "रक्त का लाल रंग किस लौहयुक्त प्रोटीन वर्णक के कारण होता है?", ["मायोग्लोबिन", "हीमोग्लोबिन (Haemoglobin)", "फाइब्रिन", "कैरोटीन"], "B", "हीमोग्लोबिन में 'हीम' नामक लौह यौगिक होता है जो ऑक्सीजन से जुड़कर रक्त को लाल बनाता है।", "NMMS MP 2022"),
        (33, "शरीर के सैनिकों (Soldiers of Body) के रूप में किन्हें जाना जाता है?", ["लाल रक्त कणिकाएं", "श्वेत रक्त कणिकाएं (WBC)", "प्लेटलेट्स", "प्लाज्मा"], "B", "WBC हानिकारक बैक्टीरिया और वायरसों को भक्षण करके शरीर को रोगों से बचाती हैं।", "NMMS Rajasthan 2023"),
        (34, "आरबीसी (लाल रक्त कणिकाएं) का जीवनकाल लगभग कितने दिनों का होता है?", ["20 से 30 दिन", "120 दिन (120 Days)", "200 दिन", "365 दिन"], "B", "RBC का निर्माण अस्थिमज्जा (Bone Marrow) में होता है और इनका जीवनकाल 120 दिन होता है।", "NMMS All India 2022"),
        (35, "मानव हृदय 1 मिनट में औसतन कितनी बार धड़कता है?", ["60 बार", "72 बार (72 times/min)", "80 बार", "100 बार"], "B", "एक सामान्य स्वस्थ वयस्क का हृदय प्रति मिनट लगभग 72 बार स्पंदन करता है।", "NMMS Gujarat 2023"),
        (36, "मानव शरीर का सामान्य तापमान कितना होता है?", ["35°C", "37°C (या 98.6°F)", "40°C", "42°C"], "B", "मानव शरीर का स्थिर तापमान 37°C या 98.6 फारेनहाइट होता है।", "NMMS Bihar 2023"),
        (37, "लार में उपस्थित कौन-सा जीवाणुनाशक एंजाइम भोजन के कीटाणुओं को मारता है?", ["टायलिन", "लाइसोजाइम (Lysozyme)", "पेप्सिन", "रेनिन"], "B", "लाइसोजाइम एंजाइम लार और आंसुओं में पाया जाता है जो जीवाणुओं की कोशिका भित्ति को तोड़ता है।", "NMMS UP 2022"),
        (38, "प्रोटीन की कमी से बच्चों में कौन-सा गंभीर कुपोषण रोग हो जाता है?", ["स्कर्वी", "क्वाशिओरकोर (Kwashiorkor)", "रतौंधी", "एनीमिया"], "B", "प्रोटीन की भारी कमी से बच्चों का पेट फूल जाता है और हाथ-पैर पतले हो जाते हैं (क्वाशिओरकोर)।", "NMMS MP 2023"),
        (39, "शरीर में लोहे (आयरन) की कमी से कौन-सा रोग हो जाता है?", ["घेंघा", "अरक्तता / एनीमिया (Anaemia)", "स्कर्वी", "मधुमेह"], "B", "आयरन की कमी से रक्त में हीमोग्लोबिन का स्तर गिर जाता है, जिससे एनीमिया होता है।", "NMMS Haryana 2023"),
        (40, "आयोडीन की कमी से कौन-सी अंतःस्रावी ग्रंथि सूजकर बढ़ जाती है?", ["पीयूष ग्रंथि", "थायरॉयड ग्रंथि (घेंघा रोग)", "अग्न्याशय", "अधिवृक्क"], "B", "थायरॉयड ग्रंथि थायरॉक्सिन हार्मोन बनाने के लिए आयोडीन लेती है; कमी होने पर सूज जाती है।", "NMMS Rajasthan 2022"),
        (41, "मानव नेत्र में किसी वस्तु का वास्तविक प्रतिबिंब किस पर्दे पर बनता है?", ["कॉर्निया पर", "आईरिस पर", "रेटिना / दृष्टिपटल पर", "पुतली पर"], "C", "नेत्र लेंस द्वारा रेटिना पर वस्तु का उल्टा एवं वास्तविक प्रतिबिंब बनता है।", "NMMS Delhi 2022"),
        (42, "नेत्र में प्रवेश करने वाले प्रकाश की मात्रा को कौन नियंत्रित करता है?", ["कॉर्निया", "परितारिका / आईरिस (Iris)", "रेटिना", "श्वेतपटल"], "B", "आईरिस पुतली के आकार को सिकोड़ या फैलाकर आंख में जाने वाले प्रकाश को नियंत्रित करती है।", "NMMS Bihar 2022"),
